# -*- coding: utf-8 -*-
# Articoli originali della redazione ARIA (testi nostri; i fatti citati vengono dalle fonti elencate in ciascun articolo)
FEN="https://fenait.org/luoghi-naturisti"
ARTICLES=[
dict(slug="scegliere-spiaggia-naturista-italia",t="Come scegliere una spiaggia naturista in Italia",
 dek="Autorizzata, presidiata o solo tollerata: tre parole che cambiano tutto. Che cosa controllare prima di mettere in borsa l’asciugamano.",
 min=4,sec="Naturismo",
 body=[("p","In Italia non tutte le spiagge dove si pratica il naturismo hanno lo stesso stato. Per chi parte, la prima domanda non è «com’è il mare?», ma «questo tratto di costa è riconosciuto?». La differenza sta nell’atto che lo consente."),
 ("h","Tre situazioni da distinguere"),
 ("p","<strong>Autorizzata</strong>: esiste un’ordinanza o una delibera del Comune che consente il naturismo in un tratto delimitato. È la tutela più solida. <strong>Presidiata da un’associazione</strong>: la pratica regge sulla presenza organizzata di una realtà naturista, senza un atto dedicato. <strong>Tollerata di fatto</strong>: frequentazione storica, ma nessun atto. Questa distinzione è quella usata dalle guide di settore; la lista che seguiamo noi, quella di FENAIT, comprende i luoghi «ufficialmente riconosciuti dai Comuni»."),
 ("h","Prima di partire"),
 ("ul",["Apri l’elenco FENAIT e individua il luogo: sono 24, ordinati da nord a sud, dalla fluviale di Varallo Sesia alle spiagge siciliane di Messina e Gela.","Controlla il sito del Comune o la pagina del luogo: alcune ordinanze si rinnovano ogni stagione e fissano date precise.","Leggi i divieti locali: in certi tratti non si può montare ombrelloni o tende, ad esempio per proteggere la nidificazione degli uccelli.","Non aspettarti servizi: in molte oasi non ci sono bar né bagni.","Porta acqua, protezione solare e un telo su cui sederti."]),
 ("h","Comportamento"),
 ("p","Nei luoghi naturisti si sta nudi, non si guarda e non si fotografa. Un saluto cortese basta; se qualcuno non vuole compagnia, la distanza si rispetta. Chi cerca altro, in questi luoghi, ha sbagliato indirizzo."),
 ("p","Le spiagge cambiano: se scopri che un’ordinanza non è più valida, segnalacelo nella community e correggiamo il numero.")],
 src=[("Elenco ufficiale FENAIT dei luoghi naturisti",FEN),("Il naturismo e la legge · FENAIT","https://fenait.org/il-naturismo-e-la-legge"),("Guida alle spiagge autorizzate (stati e distinzioni) · The Naturist Hotels","https://thenaturisthotels.com/it/blog/spiagge-naturiste-autorizzate-in-italia/")]),

dict(slug="primo-giorno-centro-naturista",t="Il primo giorno in un centro naturista",
 dek="Un campeggio o un resort naturista funziona con poche regole semplici. Eccole, prima che qualcuno te le debba spiegare.",
 min=3,sec="Naturismo",
 body=[("p","Un centro naturista è un luogo di vacanza come un altro, con la differenza che i vestiti sono facoltativi o assenti in certe zone. L’atmosfera è di solito più tranquilla di quanto si pensi: si legge, si nuota, si cucina, si fa sport."),
 ("h","Arrivo e regole"),
 ("ul",["Leggi il regolamento alla reception: spesso indica le zone dove la nudità è richiesta e quelle dove è facoltativa.","Molti centri richiedono la tessera INF o chiedono di presentarla; informati sul sito prima di partire.","Prenota dal sito ufficiale della struttura, non da intermediari che non conosci.","Alcuni centri dichiarano di non prenotare le piazzole in loco: controlla le condizioni del posto che hai scelto."]),
 ("h","Piccola etichetta"),
 ("ul",["Siediti sempre su un asciugamano, anche in piscina e nelle aree comuni.","Niente fotografie di altre persone. Anche sullo sfondo.","Il telefono resta in tasca o in tenda.","Chi ha figli o ospiti non naturisti: lo dice a chi gestisce la struttura."]),
 ("p","Il naturismo, nella definizione dell’INF-FNI, è un modo di vivere in armonia con la natura, caratterizzato dalla pratica della nudità in comune, per favorire il rispetto di sé stessi, degli altri e dell’ambiente. Il rispetto viene prima della nudità."),
 ("p","In Italia FENAIT elenca 13 centri certificati; li trovi nella sezione Naturismo di questo numero, ciascuno con il proprio sito ufficiale.")],
 src=[("Centri naturisti certificati INF-FENAIT","https://fenait.org/centri-naturisti"),("La FENAIT · definizione di naturismo","https://fenait.org/la-fenait")]),

dict(slug="consenso-cinque-domande",t="Consenso: cinque domande da farsi, e da fare",
 dek="Non è una formalità. È la parte di un incontro tra adulti che decide se resterà un bel ricordo.",
 min=3,sec="Consenso",
 body=[("p","Che si parli di una serata in un club o di un weekend con amici, il consenso non si dà una volta per tutte. Si chiede, si ascolta e si può ritirare in qualsiasi momento. Cinque domande per orientarsi."),
 ("h","1. Ho chiesto, o ho dato per scontato?"),("p","Un sorriso, un invito a ballare o un biglietto d’ingresso non sono un «sì». Se non c’è una risposta chiara, la risposta è no."),
 ("h","2. Posso accettare un «no» senza insistere?"),("p","Chi riceve un no ringrazia e si allontana. Non si negozia e non si offre da bere per far cambiare idea."),
 ("h","3. Siamo lucidi?"),("p","Alcol e sostanze alterano la capacità di scegliere. Se uno dei due non è lucido, si rimanda."),
 ("h","4. C’è una parola per fermarci?"),("p","Nelle community ZDOS la parola è ROSSO: ferma tutto, subito, senza spiegazioni. Nei locali valgono le regole del locale: chiedile prima di entrare."),
 ("h","5. Chi altro è coinvolto?"),("p","Foto, nomi e frequentazioni non sono nostre. Niente riprese, niente racconti che identificano gli altri. Alcuni club dichiarano già il divieto di telefoni e fotocamere in sala: è una tutela per tutti."),
 ("p","Tutto questo vale solo tra persone maggiorenni. Nessuna eccezione e nessun dubbio sull’età: nel dubbio, non si procede.")],
 src=[("Olimpo Club Privé · regole dichiarate (consenso, niente telefoni)","https://www.olimpoclub.com/"),("Bad Romance · informazioni per i soci","https://badromanceclub.com/")]),

dict(slug="istria-naturista",t="Istria naturista: tre indirizzi sulla stessa costa",
 dek="Valalta, Koversada e Solaris: tre centri storici nel raggio di pochi chilometri, ciascuno con le sue condizioni.",
 min=3,sec="Viaggi",
 body=[("p","L’Istria croata è una delle mete naturiste più frequentate d’Europa. Sul litorale tra Rovinj e Poreč si trovano tre nomi noti. Ecco cosa dichiarano i rispettivi siti ufficiali; tutto il resto, prezzi compresi, si legge sul sito di ciascuno."),
 ("h","Koversada, Vrsar"),("p","Il gestore, Maistra, la descrive come il centro naturista più antico d’Europa tuttora in attività, attivo dal 1961 come campeggio naturista, con piazzole e case mobili nella baia di Lim. Per il 2027 indica l’apertura dal 23 aprile al 10 ottobre."),
 ("h","Valalta, Rovinj"),("p","Campeggio FKK nella stessa area, con oltre quattro chilometri di spiaggia dichiarati. La stagione 2027 va dall’1 maggio al 30 settembre. Il sito avvisa che in loco non si prenotano le piazzole: leggi le condizioni prima di mettere in viaggio la roulotte."),
 ("h","Solaris, Poreč"),("p","Sulla penisola di Lanterna, a metà strada tra Novigrad e Poreč: 2,5 km di costa, piazzole, camere e appartamenti, gestito da Valamar."),
 ("h","Come arrivare"),("p","Per arrivare in zona puoi considerare l’aeroporto di Pola; nella sezione Prenota trovi i link alla ricerca di auto a noleggio per Pola e agli alloggi della zona."),
 ("p","Che tu scelga uno o l’altro, valgono le stesse regole: rispetto, niente foto, prenotazione dai canali ufficiali.")],
 src=[("Koversada Uncovered Naturist Campsite · Maistra","https://www.maistra.com/properties/koversada-park-camping-resort/koversada-uncovered-naturist-campsite/"),("FKK Valalta · sito ufficiale","https://www.valalta.hr/en/"),("Camping Solaris · Valamar","https://www.valamarcamping.com/solaris-naturist-resort-porec")]),

dict(slug="naturismo-e-legge-italia",t="Naturismo e legge in Italia: sei Regioni, nessuna norma nazionale",
 dek="Che cosa si può fare, dove e con quali rischi. Una lettura per orientarsi, non un parere legale.",
 min=3,sec="Legalità",
 body=[("p","Secondo FENAIT, la pratica del naturismo in Italia non è regolata da una legge approvata dal Parlamento. Le proposte non mancano, la prima risale al 1993, ma nessuna è arrivata all’approvazione. Il vuoto è stato in parte colmato dalle Regioni."),
 ("h","Le sei leggi regionali"),("p","FENAIT cita leggi di Piemonte, Lombardia, Veneto, Emilia-Romagna, Abruzzo e Sardegna, che tutelano e regolano la pratica sia nei luoghi pubblici sia nelle attività ricettive."),
 ("h","Spiagge riconosciute"),("p","Le spiagge in cui il naturismo è consentito sono quelle riconosciute dai Comuni: l’elenco ufficiale di FENAIT ne conta oggi 24. Fuori da quelle aree, restare nudi in un luogo pubblico può portare a sanzioni. Alcune ordinanze, inoltre, si rinnovano ogni stagione."),
 ("h","Che cosa fare, in pratica"),
 ("ul",["Verifica sempre il luogo sull’elenco ufficiale e sul sito del Comune.","Rispetta i confini del tratto riservato e i divieti indicati.","Nei centri privati vale il regolamento della struttura.","Se hai dubbi su un caso concreto, chiedi al Comune o a un avvocato."]),
 ("p","Questo articolo è informazione generale: non sostituisce una consulenza legale.")],
 src=[("Il naturismo e la legge · FENAIT","https://fenait.org/il-naturismo-e-la-legge"),("Elenco ufficiale dei luoghi naturisti · FENAIT",FEN)]),

dict(slug="leggere-regolamento-club",t="Prima di entrare: come si legge il regolamento di un club",
 dek="Tessera, età, dress code, prenotazione, regole sulle foto: i club privati dichiarano tutto sul proprio sito. Basta saperlo cercare.",
 min=3,sec="Lifestyle",
 body=[("p","I club privé per coppie e single sono associazioni private riservate a soci maggiorenni. Per questo ciascuno pubblica le proprie condizioni, e quelle, non le voci in rete, sono la fonte da leggere."),
 ("h","Che cosa cercare sul sito ufficiale"),
 ("ul",["<strong>Età e tesseramento</strong>: alcuni locali indicano una soglia di età per i soci (Bad Romance, ad esempio, scrive «soci 21+») e il tesseramento in sede con documento d’identità.","<strong>Giorni e orari</strong>: ci sono club aperti solo alcuni giorni; Olimpo indica giovedì, venerdì e sabato.","<strong>Prenotazione</strong>: per alcune serate è obbligatoria, per altre solo consigliata; i contatti ufficiali sono sul sito.","<strong>Regole di condotta</strong>: consenso, rispetto, divieto di telefoni e fotocamere sono dichiarati da alcuni club e vanno sempre rispettati.","<strong>Dress code</strong>: dove richiesto, è indicato nella pagina dell’evento."]),
 ("h","Diffida di"),
 ("ul",["Annunci che chiedono pagamenti anticipati fuori dai canali del club.","Gruppi che promettono incontri a pagamento: non rientrano in ciò che pubblichiamo.","Persone che insistono per avere foto o dati personali."]),
 ("p","I club descritti in questo numero hanno un sito ufficiale raggiungibile; non siamo affiliati a nessuno di loro e non riceviamo compensi.")],
 src=[("Bad Romance · eventi e soci","https://badromanceclub.com/ita_eventi/"),("Olimpo Club Privé","https://www.olimpoclub.com/"),("Infinito Club Privé","https://www.infinitoclubmilano.com/"),("Club Privé Milano 369 · eventi","https://www.club369milano.it/eventi/")]),
]
